head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil52720";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — isOk

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_sessionFill();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil52720.onpageload' });
    }
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        await scwin.checkSave();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil52720.onpageload' }); }
};

// 세션 사용자 결선 (어휘 session_attribute 1건 — gcc $c.session.getUserInfo)

/**
 * @method
 * @name init_sessionFill
 * @description 초기화 — session Fill
 * @returns {void}
 * @hidden N
 */
scwin.init_sessionFill = function () {
    const names = ["usrId"];
    function fill() {
        for (let i = 0; i < names.length; i++) {
            let v; try { v = $c.session.getUserInfo(names[i]); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil52720' }); v = undefined; }
            if (v === undefined || v === null || v === '') { continue; }
            const token = '${session.user.' + names[i] + '}';
            let r0 = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document); r0 = r0.body || r0; const doc = r0.ownerDocument || r0; const w = doc.createTreeWalker(r0, NodeFilter.SHOW_TEXT);
            let n; while ((n = w.nextNode())) { if (n.nodeValue.indexOf(token) >= 0) { n.nodeValue = n.nodeValue.split(token).join(v); } }
            const ins = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelectorAll('input, textarea');
            for (let j = 0; j < ins.length; j++) { if (ins[j].value && ins[j].value.indexOf(token) >= 0) { ins[j].value = ins[j].value.split(token).join(v); } }
        }
    }
    fill();
};

// [A] 초기 목록 미해결 — jldfil52720: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_saveAdjReq_onclick
 * @description 「저장」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_saveAdjReq_onclick = async function(e){
    try {
        await scwin.saveAdjReq()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil52720.btn_saveAdjReq_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name saveAdjReq
 * @description save Adj Req 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.saveAdjReq = async function () {
    const msg = "수정 승인 후 다시 접수 될때까지 같은 업무에 대해서 수정요청 할 수 없습니다. \r\n수정요청 하시겠습니까?";
    if (await scwin.checkValue()) {
        if (await $c.win.confirm(msg)) {
            // TODO Stage2(규칙 19): jQuery — 폼 제출 → $c.sbm 서브미션(규칙 6, B-4 제출 주소 회신)
            $("#adjReqForm").submit();
        }
    }
};

/**
 * @method
 * @name checkSave
 * @description check Save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkSave = async function () {
    const isOk = (String(((dma_pageContext.get("isOk") ?? "")) == null ? '' : ((dma_pageContext.get("isOk") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("isOk") ?? "")) == null ? '' : ((dma_pageContext.get("isOk") ?? ""))));
    if (isOk !== '') {
        if (isOk === 'true') {
            await $c.win.alert('수정요청 되었습니다.');
        } else {
            await $c.win.alert('수정요청 중 오류가 발생 되었습니다.');
        }
        (function () { const o = $c.win.getOpenerScope(); if (o) { $c.win.setPageFrameSrc($c.win.getFrame(o), null); } else { /* TODO Stage2: [sdd] 부모 창을 못 찾았다 — 새로고침하지 않는다(자기 화면을 다시 열면 무한 고리가 된다) */ } })();
        $c.win.closePopup();
    }
};

/**
 * @method
 * @name checkValue
 * @description check Value 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkValue = async function () {
    if ($c.util.getComponent('txa_chgRsn').getValue().length === 0) {
        await $c.win.alert('수정 사유를 입력 하세요.');
        return false;
    }
    if (dma_hiddenStore.get("slc_listBzDtlTpCd") === "") {
        await $c.win.alert('수정 요청 업무를 선택 하세요.');
        return false;
    }
    return true;
};
